import { Buffer } from "node:buffer";
function dimensions(b) {
  if (b[0] === 0xff && b[1] === 0xd8) {
    let p = 2;
    while (p + 9 < b.length) {
      if (b[p++] !== 0xff) continue;
      let marker = b[p++];
      while (marker === 0xff) marker = b[p++];
      if (marker === 0xd8 || marker === 0xd9 || (marker >= 0xd0 && marker <= 0xd7)) continue;
      const size = (b[p] << 8) | b[p + 1];
      if (size < 2 || p + size > b.length) throw Error("Invalid JPEG segment");
      if (
        [0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].includes(
          marker,
        )
      )
        return {
          height: (b[p + 3] << 8) | b[p + 4],
          width: (b[p + 5] << 8) | b[p + 6],
          mime: "image/jpeg",
        };
      p += size;
    }
  }
  if (b.length > 24 && b[0] === 137 && b[1] === 80 && b[2] === 78 && b[3] === 71) {
    const u = (i) => (b[i] * 16777216 + (b[i + 1] << 16) + (b[i + 2] << 8) + b[i + 3]) >>> 0;
    return { width: u(16), height: u(20), mime: "image/png" };
  }
  throw Error("Use a JPEG or PNG image");
}
export default async function detect({ imageUrl, apiKey, model, subject }, ctx) {
  if (!/^https:\/\//.test(imageUrl) || !apiKey || !model || !subject)
    throw Error("Configure image URL, subject and Gemini key");
  const chunk = 524288,
    parts = [];
  let offset = 0,
    total = null,
    validator = "";
  do {
    const h = { Range: `bytes=${offset}-${offset + chunk - 1}` };
    if (validator) h["If-Range"] = validator;
    const r = await ctx.fetch(imageUrl, { headers: h });
    if (r.status !== 200 && r.status !== 206) throw Error("Image download failed");
    const bytes = new Uint8Array(await r.arrayBuffer());
    if (r.status === 200) {
      if (offset) throw Error("Image changed while downloading");
      parts.push(bytes);
      total = bytes.length;
      offset = total;
      break;
    }
    const m = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(r.headers.get("content-range") || "");
    if (!m || Number(m[1]) !== offset || Number(m[2]) - offset + 1 !== bytes.length)
      throw Error("Invalid image range");
    if (total !== null && total !== Number(m[3])) throw Error("Image changed during download");
    total = Number(m[3]);
    if (!validator) validator = r.headers.get("etag") || r.headers.get("last-modified") || "";
    if (!validator && total > bytes.length)
      throw Error("Large image download needs an ETag or Last-Modified validator");
    parts.push(bytes);
    offset += bytes.length;
  } while (offset < total);
  if (!total || total > 20 * 1024 * 1024) throw Error("Image must be at most 20 MiB");
  const bytes = new Uint8Array(total);
  let pos = 0;
  for (const p of parts) {
    bytes.set(p, pos);
    pos += p.length;
  }
  const { width, height, mime } = dimensions(bytes);
  if (!width || !height) throw Error("Image dimensions missing");
  const start = await ctx.fetch("https://generativelanguage.googleapis.com/upload/v1beta/files", {
    method: "POST",
    headers: {
      "x-goog-api-key": apiKey,
      "x-goog-upload-protocol": "resumable",
      "x-goog-upload-command": "start",
      "x-goog-upload-header-content-length": String(bytes.length),
      "x-goog-upload-header-content-type": mime,
      "content-type": "application/json",
    },
    body: JSON.stringify({ file: { display_name: "detection-image" } }),
  });
  if (!start.ok) throw Error("Gemini upload initialization failed");
  const upload = start.headers.get("x-goog-upload-url");
  if (!upload || new URL(upload).hostname !== "generativelanguage.googleapis.com")
    throw Error("Unexpected Gemini upload host");
  let uploaded;
  for (let p = 0; p < bytes.length; p += chunk) {
    const end = Math.min(p + chunk, bytes.length),
      last = end === bytes.length,
      r = await ctx.fetch(upload, {
        method: "POST",
        headers: {
          "x-goog-upload-offset": String(p),
          "x-goog-upload-command": last ? "upload, finalize" : "upload",
        },
        body: bytes.slice(p, end),
      });
    if (!r.ok) throw Error("Image upload failed or outcome unknown");
    if (last) uploaded = await r.json();
  }
  const uri = uploaded?.file?.uri;
  if (typeof uri !== "string") throw Error("Gemini image upload unconfirmed");
  const response = await ctx.fetch(
    "https://generativelanguage.googleapis.com/v1beta/models/" +
      encodeURIComponent(model) +
      ":generateContent",
    {
      method: "POST",
      headers: { "x-goog-api-key": apiKey, "content-type": "application/json" },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              { file_data: { mime_type: mime, file_uri: uri } },
              {
                text:
                  "Detect all " +
                  subject +
                  " in this image. Return each bounding box as [ymin,xmin,ymax,xmax], normalized to 0–1000.",
              },
            ],
          },
        ],
        generationConfig: {
          response_mime_type: "application/json",
          response_schema: {
            type: "ARRAY",
            items: {
              type: "OBJECT",
              properties: {
                box_2d: { type: "ARRAY", items: { type: "NUMBER" } },
                label: { type: "STRING" },
              },
              required: ["box_2d"],
            },
          },
        },
      }),
    },
  );
  if (!response.ok) throw Error("Gemini detection failed");
  const output = await response.json(),
    candidate = output.candidates?.[0];
  if (candidate?.finishReason !== "STOP") throw Error("Gemini detection incomplete");
  const raw = JSON.parse((candidate.content?.parts ?? []).map((x) => x.text ?? "").join(""));
  if (!Array.isArray(raw)) throw Error("Invalid detections");
  const boxes = raw.map((x) => {
    const a = x.box_2d;
    if (
      !Array.isArray(a) ||
      a.length !== 4 ||
      a.some((v) => !Number.isFinite(v) || v < 0 || v > 1000) ||
      a[0] > a[2] ||
      a[1] > a[3]
    )
      throw Error("Invalid bounding box");
    return {
      xmin: (a[1] * width) / 1000,
      ymin: (a[0] * height) / 1000,
      xmax: (a[3] * width) / 1000,
      ymax: (a[2] * height) / 1000,
      label: String(x.label ?? ""),
    };
  });
  const rects = boxes
    .map(
      (b) =>
        `<rect x="${b.xmin}" y="${b.ymin}" width="${b.xmax - b.xmin}" height="${b.ymax - b.ymin}" fill="none" stroke="#ff00f2" stroke-opacity="0.47" stroke-width="4"/>`,
    )
    .join("");
  let encoded = "";
  for (let i = 0; i < bytes.length; i += 196608)
    encoded += Buffer.from(bytes.slice(i, i + 196608)).toString("base64");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><image width="${width}" height="${height}" href="data:${mime};base64,${encoded}"/>${rects}</svg>`;
  const file = await ctx.artifact.put(new TextEncoder().encode(svg), {
    name: "detections.svg",
    mediaType: "image/svg+xml",
  });
  return { file, boxes };
}
